package com.autoops.execution.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="machine_runs")public class MachineRun{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="execution_id",nullable=false)private Long executionId;@Column(name="machine_id",nullable=false)private Long machineId;@Column(name="credential_id")private Long credentialId;@Column(nullable=false)private String status="PENDING";@Column(name="failure_reason",columnDefinition="text")private String failureReason;@Column(name="started_at")private Instant startedAt;@Column(name="finished_at")private Instant finishedAt;public Long getId(){return id;}public void setExecutionId(Long v){executionId=v;}public void setMachineId(Long v){machineId=v;}public void setCredentialId(Long v){credentialId=v;}public void setStatus(String v){status=v;}}
